import{_ as a,o as e,c as s,a2 as d}from"./chunks/framework.CAKCj7G0.js";const m=JSON.parse('{"title":"Pager组件","description":"","frontmatter":{},"headers":[],"relativePath":"DuOneClass/08.Vue/06.组件事件.md","filePath":"DuOneClass/08.Vue/06.组件事件.md"}'),n={name:"DuOneClass/08.Vue/06.组件事件.md"};function r(l,t,i,p,o,h){return e(),s("div",null,[...t[0]||(t[0]=[d(`<h1 id="pager组件" tabindex="-1">Pager组件 <a class="header-anchor" href="#pager组件" aria-label="Permalink to &quot;Pager组件&quot;">​</a></h1><p><img src="https://s2.loli.net/2025/02/03/jM2PB53QxvrJ6fH.png" alt=""></p><h2 id="属性" tabindex="-1">属性 <a class="header-anchor" href="#属性" aria-label="Permalink to &quot;属性&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性名</th><th>含义</th><th>类型</th><th>必填</th><th>默认值</th></tr></thead><tbody><tr><td>current</td><td>当前页码</td><td>Number</td><td>否</td><td>1</td></tr><tr><td>total</td><td>总数据量</td><td>Number</td><td>否</td><td>0</td></tr><tr><td>limit</td><td>页容量</td><td>Number</td><td>否</td><td>10</td></tr><tr><td>visibleNumber</td><td>可见页码数</td><td>Number</td><td>否</td><td>10</td></tr></tbody></table><h2 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h2><table tabindex="0"><thead><tr><th>事件名</th><th>含义</th><th>事件参数</th><th>参数类型</th></tr></thead><tbody><tr><td>pageChange</td><td>页码变化</td><td>新的页码</td><td>Number</td></tr></tbody></table><h1 id="知识点" tabindex="-1">知识点 <a class="header-anchor" href="#知识点" aria-label="Permalink to &quot;知识点&quot;">​</a></h1><ol><li><p><strong>全局样式</strong></p></li><li><p><strong>v-if 和 v-show</strong></p><p><img src="https://s2.loli.net/2024/06/19/F5lReWsvYz3CD1g.png" alt="image-20201113133827438"></p><hr><p><img src="https://s2.loli.net/2024/06/19/ywdUgjAt7ka1spT.png" alt="image-20201113134051281"></p><p><strong>面试题：v-if 和 v-show 有什么区别？</strong></p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>v-if能够控制是否生成vnode，也就间接控制了是否生成对应的dom。当v-if为true时，会生成对应的vnode，并生成对应的dom元素；当其为false时，不会生成对应的vnode，自然不会生成任何的dom元素。</span></span>
<span class="line"><span>v-show始终会生成vnode，也就间接导致了始终生成dom。它只是控制dom的display属性，当v-show为true时，不做任何处理；当其为false时，生成的dom的display属性为none。</span></span>
<span class="line"><span>使用v-if可以有效的减少树的节点和渲染量，但也会导致树的不稳定；而使用v-show可以保持树的稳定，但不能减少树的节点和渲染量。</span></span>
<span class="line"><span>因此，在实际开发中，显示状态变化频繁的情况下应该使用v-show，以保持树的稳定；显示状态变化较少时应该使用v-if，以减少树的节点和渲染量。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div></li><li><p><strong>组件事件</strong></p><p><img src="https://s2.loli.net/2024/06/19/1ZEd4BwV8rAXiaM.png" alt="image-20201113134557175"></p><p>抛出事件：子组件在某个时候发生了一件事，但自身无法处理，于是通过事件的方式通知父组件处理</p><p>事件参数：子组件抛出事件时，传递给父组件的数据</p><p>注册事件：父组件申明，当子组件发生某件事的时候，自身将做出一些处理</p></li></ol>`,8)])])}const b=a(n,[["render",r]]);export{m as __pageData,b as default};
